interface FiltrosAcervo {
  area?: Area;
  tipo?: ItemAcervo["tipo"];
}

/**
 * Busca no acervo: cada termo precisa aparecer no título, na fonte ou na descrição (sem acento nem caixa, como a
 * busca dos guias). Os filtros de área e tipo valem junto. Sem termo, devolve tudo o que passa pelos filtros.
 */
export function buscarAcervo(q: string, filtros: FiltrosAcervo = {}): ItemAcervo[] {
  return ACERVO.filter((it) => {
    if (filtros.area && it.area !== filtros.area) return false;
    if (filtros.tipo && it.tipo !== filtros.tipo) return false;
    return casaBusca(normalizarBusca(`${it.titulo} ${it.fonte} ${it.descricao}`), q);
  });
}
